#!/usr/bin/env python3
"""Bygg et lite, selvstendig arkivgalleri fra kontrollerte råfilbindinger."""
import hashlib
import json
from pathlib import Path

R = Path(__file__).resolve().parents[1]
A = R / 'art/photoreal'
data = json.loads((A / 'catalog.json').read_text())
for row in data['rows']:
    for key in ['source', 'photo']:
        path = R / row[key]
        assert hashlib.sha256(path.read_bytes()).hexdigest() == row[key + '_sha256']
    if row.get('prompt'):
        assert (R / row['prompt']).is_file()
page = r'''<!doctype html><html lang="nb"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Moonstone: HD-arkiv</title><style>*{box-sizing:border-box}body{margin:20px auto;padding:0 18px;max-width:1450px;background:#13212a;color:#e7eee9;font:16px/1.5 system-ui}a{color:#c3dfb9}h1{font:36px Georgia}p{max-width:1100px}button,select,input{padding:9px;margin:4px 6px 4px 0;max-width:100%}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}article{background:#21313b;padding:14px;border-radius:8px;overflow-wrap:anywhere}h2{font-size:16px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:8px}.image{height:270px;background:repeating-conic-gradient(#879399 0 25%,#cbd0d2 0 50%) 0/18px 18px;display:flex;justify-content:center;align-items:center}.image img{max-width:100%;max-height:100%;object-fit:contain}.source{image-rendering:pixelated}.white .image{background:white}.black .image{background:black}.note{font-size:13px;max-height:130px;overflow:auto}.state{color:#bddbbc}small{font-size:12px}.controls{position:sticky;top:0;background:#13212a;padding:10px 0;z-index:1}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.grid{grid-template-columns:1fr}.image{height:300px}}</style><h1>Moonstone: HD-arkiv</h1><p>Separate original-/foto-par, prompter og bevarte råversjoner. Et arkivbilde er ikke automatisk ferdig eller aktivert i spillet. Standardpakken har 48 bilder; de fem hele blå metodeposene ligger ved siden av produksjonen av hver enkelt figurrute.</p><p><a href="../../docs/hd-grafikk.md">Spillintegrasjon</a> · <a href="catalog.json">Kilde-/bildehasher og kontrollnotater</a></p><div class="controls"><input id="search" placeholder="Filnavn eller rutenummer" aria-label="Søk"><select id="filter" aria-label="Status"><option value="all">Alle valgte utkast</option><option value="enabled">Aktivert i spillet</option><option value="revision">Trenger retting</option></select><select id="bg" aria-label="Bakgrunn"><option value="checker">Sjakk</option><option value="white">Hvitt</option><option value="black">Svart</option></select><button id="prev">Forrige</button><span id="page"></span><button id="next">Neste</button><div id="count"></div></div><main class="grid"></main><script>const D=__DATA__;let page=0,rows=D.rows;const $=s=>document.querySelector(s),url=s=>'../../'+s;function add(el,tag,text,cls){const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;el.append(n);return n;}function draw(){$('main').replaceChildren();const pages=Math.max(1,Math.ceil(rows.length/12));page=Math.min(page,pages-1);$('#page').textContent='Side '+(page+1)+' av '+pages;$('#count').textContent=rows.length+' valgte oppføringer, '+D.raw_png_files+' rå-PNG i arkivet';$('#prev').disabled=!page;$('#next').disabled=page>=pages-1;for(const r of rows.slice(page*12,page*12+12)){const a=add($('main'),'article','');a.dataset.id=r.id;add(a,'h2',r.id);add(a,'p',r.status+(r.enabled_in_game?' · Aktivert i standardpakken':' · Ikke aktivert'),'state');const pair=add(a,'div','','pair');for(const k of ['source','photo']){const box=add(pair,'div','','image'),im=document.createElement('img');im.src=url(r[k]);im.alt=k==='source'?'Original':'Urørt fotoutkast';if(k==='source')im.className='source';box.append(im);}add(a,'small',r.palette_label);const links=add(a,'p','');for(const[k,label]of[['photo','Råbilde'],['prompt','Prompt']])if(r[k]){const link=add(links,'a',label+' ');link.href=url(r[k]);}add(a,'p',(r.notes||[]).join(' '),'note');}}function filter(){const q=$('#search').value.trim().toLowerCase(),mode=$('#filter').value;rows=D.rows.filter(r=>(!q||r.id.toLowerCase().includes(q))&&(mode==='all'||mode==='enabled'&&r.enabled_in_game||mode==='revision'&&/revision|rejected|failed/.test(r.status)));page=0;draw();}$('#search').oninput=filter;$('#filter').onchange=filter;$('#prev').onclick=()=>{page--;draw();};$('#next').onclick=()=>{page++;draw();};$('#bg').onchange=()=>document.body.className=$('#bg').value;draw();</script></html>'''
(A / 'index.html').write_text(page.replace('__DATA__', json.dumps(data, ensure_ascii=False, separators=(',', ':')).replace('</', '<\\/')))
print(json.dumps({'entries': len(data['rows']), 'raw_png_files': data['raw_png_files']}))
